async function startup(){
 const bundled = [...suppliedLasers,...defaultComponents,holderAsset];
 const bundledIds = new Set(bundled.map(asset => asset.id));
 if(hostedAccounts) $('saveState').textContent='Save to account or download';
 else try {
  db = await new Promise((resolve,reject)=>{
   const request = indexedDB.open('optical-workbench-v2',1);
   request.onupgradeneeded=()=>request.result.createObjectStore('workspace');
   request.onsuccess=()=>resolve(request.result);
   request.onerror=()=>reject(request.error);
  });
  const saved = await new Promise((resolve,reject)=>{
   const request = db.transaction('workspace','readonly').objectStore('workspace').get('current');
   request.onsuccess=()=>resolve(request.result);
   request.onerror=()=>reject(request.error);
  });
  if(saved){
   const assets = saved.catalog.map(validateAsset);
   const restored = validateProject({...saved.state,assets:[]},assets);
   for(const asset of assets){
    const retiredDemo = asset.note === 'Original demo geometry' && (bundledIds.has(asset.id) || asset.id === 'demo-laser');
    if(!retiredDemo){mergeCatalog([asset]);continue;}
    const placements = restored.items.filter(item => item.assetId === asset.id);
    if(!placements.length)continue;
    const legacyId=uid();
    mergeCatalog([{...asset,id:legacyId,deleted:true}]);
    for(const item of placements)item.assetId=legacyId;
   }
   delete restored.assets;
   state=restored;
   $('saveState').textContent='Restored from this browser';
  }
 } catch {
  $('saveState').textContent='Use Save project / Export library to keep work';
 }
 for(const asset of bundled){
  const prior = catalog.get(asset.id);
  if(!prior || (prior.geometryRevision||0)<(asset.geometryRevision||0))catalog.set(asset.id,structuredClone(asset));
 }
 renderUI();
 view('iso');
 $('loading').hidden=true;
}
defaultUI=createDefaultUI({$,item,catalog,objects,checkpoint,commit});studioUI({THREE,scene,camera,objects,getState:()=>state,item,renderer,viewport,setMode});
if(hostedAccounts){$('save').textContent='Download project';accountUI=mountAccountUI({projectData,openProject,hasWorkspace:()=>!!(state.board||state.items.length),toast});}
startup();
renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera);if($('importDialog').open&&previewModel){pControls.update();pRenderer.render(pScene,pCamera)}});




